def make(i, row):
    tag, prompt, opts, answer, reason = row
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = next(o['id'] for o in options if o['text'] == answer)
    steps = [f'讀題定位：圈出「{tag}」以及高度、氣壓、空氣重量、面積、溫度或天氣條件。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合大氣壓力與測量模型。', '排除誘答：分清壓力、總力、氣壓計讀值與天氣推論，並避免把單一變因當成唯一原因。', '最後回查：確認單位、控制條件、力的方向與證據適用範圍都和題幹一致。']
